import{_ as s,c as t,o as r,j as e,a as n}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"周易尚氏學自序","description":"周易尚氏學 - 周易尚氏學自序","frontmatter":{"title":"周易尚氏學自序","description":"周易尚氏學 - 周易尚氏學自序"},"headers":[],"relativePath":"classics/shangshi/003.md","filePath":"classics/shangshi/003.md"}'),i={name:"classics/shangshi/003.md"};function c(o,a,l,d,p,h){return r(),t("div",null,[...a[0]||(a[0]=[e("h1",{id:"周易尚氏學自序",tabindex:"-1"},[n("周易尚氏學自序 "),e("a",{class:"header-anchor",href:"#周易尚氏學自序","aria-label":"Permalink to “周易尚氏學自序”"},"​")],-1),e("p",null,"易理至明也。而說者多誤。說何以誤。厥有二因。一因易理之失傳。太史公曰。易以道陰陽。陰陽之理。同性相敵。異性相感。艮傳雲上下敵應。不相與也。謂陽應陽陰應陰為敵也。中孚六三雲得敵。同人九三曰敵剛。謂陰比陰陽比陽為敵也。陰遇陰。陽遇陽。既為敵而不相與。則不能為朋友為類明矣。鹹傳曰二氣感應以相與。恆曰剛柔皆應。夫陰陽相與相應。則必相求而為朋友為類明矣。復曰朋來無咎。謂陽來也。陰以陽為朋也。損曰一人行則得其友。謂陽行至上而據二陰也。陽以陰為友也。頤六二曰行失類也。謂陰不遇陽也。至明白也。乃說者於坤上六。謂陰陽相戰爭。相傷而出血矣。於文言謂陰陽相忌相疑矣。以陽遇陽為朋。陰遇陰為友為類矣。同性相敵。異性相感之理一失。於是初四二五三上陽應陽陰應陰者謂之失應。人尚知之。至於陽比陽陰比陰。如夬垢之三四。如頤之六二。說者則茫然。於是全部易。如徵兇。往吝。往不勝。壯於趾。其行次且。及慎所之等辭。全不知其故矣。又如陽遇重陰。陰遇重陽而當位者。所謂往吉。徵吉。利涉。利往。上合志也。此其義宋蔡淵曾創言之。而未大行。於是全部易爻象若是者。自漢迄清。說者亦莫明其故。而用爻變矣。又如陽爻，下乘重陰者亦多吉。與前臨重陰同也。蹇九三日內喜之也。說甚明也。乃亦失傳。於是頤上九之利涉。蒙上九漸九三之利禦寇。皆不知所謂矣。有此一因。於是易解之誤者。十而四五。其次則象學失傳。說卦乃自古相傳之卦象。祗說其綱領。以為萬象之引伸。並示其推廣之義。如干為馬。坤震坎亦可為馬。幹為龍。震亦可為龍。巽為木。艮坎亦可為木。非謂甲卦象此物。乙卦即不許再象也。視其義何如耳。至文王時。又歷數千年。其所演易象。必益廣益精。故周易所用象。往往與說卦不同。說卦以坎為月。經則多以兌為月。月生西。坎兌皆位西也。說卦以離為龜。經則以艮為龜。離為龜。取其外堅。艮亦外堅也。此推而益廣也。且有與說卦相反者。說卦以兌為少女。以艮為少男。而經則以兌為老婦，以艮為祖為丈夫。說卦以震為長男。巽為長女。經則以震為小子。巽為少女 (女妻即少女) 。蓋以甲乙言。先生者長。後生者少。而以一人言。則初生者少。行至上而老也。此演而益精也。自東漢迄清。於此等義例。都未能明。見經所用象。為說卦所無。則用卦變爻變或爻辰以求之。謬法流傳。二千年如一日。加此一因。於是易解之誤者。十而七八矣。以二千年相承之易說。今忽謂其誤。以一人之是。謂千百人皆非。毋乃駭眾。然而易象固在也。易理固存也。本易理以詁易辭。如磁鐵之吸引。由易辭以準易象。如規鑿之相投。固不誣也。以為之者少。旁無師友之助。以違之者眾。更無聲氣之同。然而我見固如斯也。我說無一創也。以我之說。仍以周易所言之理。推而正說者之誤。俾卦爻辭復其本有之易理也。其先儒舊說。與易理合者。如許慎荀爽九家之詁龍戰。如子夏傳荀爽之詁得敵，靡不因也，其與易理盩者。雖千百人皆如此言。而必反之。如虞翻以陽遇陽為朋。陰遇陰為類等是也。至於卦象之誤者。非我能創造新象。仍周易原有之象。說者失之。今證以左傳國語。周公時訓與卦氣圖。證以焦氏易林郭璞洞林。迴環互證而得其象也。及其既得而求其本。仍在周易。如坤之為水為魚。震之為輹等象是也。然而我之說不敢必謂其是也。更不敢自匿其非也。故名曰周易尚氏學。以質世之治易者。經者天下之公物。非一人所得私。理者天地之自然。非偏執所能改。倘學易之君子。見是編而揚搉其是非。糾正其疏漏。則日夜所祈禱者也。",-1)])])}const f=s(i,[["render",c]]);export{_ as __pageData,f as default};
